commands.command:
/usr/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Operations</title>
  <style>
    :root {
      --background: #f6f3eb;
      --foreground: #163b43;
      --space: 12px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      background: var(--background);
      color: var(--foreground);
      font: 16px/1.5 system-ui;
    }

    main {
      width: min(100% - 96px, 960px);
      margin: 0 auto;
      padding: 48px 0;
    }

    h1 {
      margin: 0 0 36px;
      font-size: 32px;
      font-weight: 600;
      line-height: 1.2;
      letter-spacing: -0.02em;
    }

    .toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: var(--space) 24px;
      margin-bottom: 24px;
    }

    label {
      display: flex;
      align-items: center;
      gap: var(--space);
    }

    select {
      min-width: 144px;
      min-height: 44px;
      padding: 8px var(--space);
      border: 1px solid var(--foreground);
      border-radius: 0;
      background: var(--background);
      color: var(--foreground);
      font: inherit;
      cursor: pointer;
    }

    select:focus-visible {
      outline: 2px solid var(--foreground);
      outline-offset: 3px;
    }

    #count {
      margin: 0;
      font-variant-numeric: tabular-nums;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      text-align: left;
    }

    th, td {
      padding: 18px var(--space);
      border-bottom: 1px solid color-mix(in srgb, var(--foreground) 20%, transparent);
      vertical-align: top;
      overflow-wrap: anywhere;
    }

    th {
      padding-top: var(--space);
      padding-bottom: var(--space);
      border-bottom-color: var(--foreground);
      font-weight: 600;
    }

    th:first-child, td:first-child { padding-left: 0; width: 65%; }
    th:last-child, td:last-child { padding-right: 0; }

    @media (max-width: 600px) {
      main {
        width: calc(100% - 48px);
        padding: 24px 0;
      }

      h1 { margin-bottom: 24px; }
      .toolbar { gap: var(--space); }
      th:first-child, td:first-child { width: 60%; }
    }

    @media (max-width: 360px) {
      main { width: calc(100% - 24px); }
      .toolbar { align-items: flex-start; flex-direction: column; }
    }
  </style>
</head>
<body>
  <main>
    <h1>Operations</h1>
    <div class="toolbar">
      <label for="filter">Status
        <select id="filter">
          <option>All</option>
          <option>Ready</option>
        </select>
      </label>
      <p id="count" aria-live="polite">2 projects</p>
    </div>
    <table aria-label="Project status">
      <thead>
        <tr><th scope="col">Project</th><th scope="col">Status</th></tr>
      </thead>
      <tbody>
        <tr data-row><td>Tidal</td><td>Ready</td></tr>
        <tr data-row><td>Mountain</td><td>Pending</td></tr>
      </tbody>
    </table>
  </main>
  <script>filter.onchange=()=>{let count=0;document.querySelectorAll('"'[data-row]').forEach(r=>{r.hidden=filter.value"'!=='"'All'&&"'!r.textContent.includes(filter.value);if(!r.hidden)count++});document.querySelector('"'#count').textContent=count+' projects'};</script>
</body>
</html>
EOF
cat > NOTES.md <<'EOF'
- Scope: spacing and responsive usability in index.html; table content, filter options, IDs, and filtering/count script preserved.
- Parameters: existing #f6f3eb / #163b43 colors and system font; 12px spacing base, 960px content maximum, 600px / 360px responsive breakpoints, 44px minimum select height. No media or motion added.
- Validation: shell content checks only. Browser/runtime behavior, visual layout, and keyboard interaction remain unverified; central observer owns qualification and independent review.
EOF
# Small source-content check; no browser or runtime execution.
test \""'$(rg -c '"'<tr data-row>' index.html)\" = 2 &&
rg -q '<tr data-row><td>Tidal</td><td>Ready</td></tr>' index.html &&
rg -q '<tr data-row><td>Mountain</td><td>Pending</td></tr>' index.html &&
rg -q '<option>All</option>' index.html &&
rg -q '<option>Ready</option>' index.html &&
rg -q 'aria-live=\"polite\">2 projects</p>' index.html &&
rg -Fq \"filter.onchange=()=>{let count=0;document.querySelectorAll('[data-row]').forEach(r=>{r.hidden=filter.value"'!=='"'All'&&"'!r.textContent.includes(filter.value);if(!r.hidden)count++});document.querySelector('"'#count').textContent=count+' projects'};\" index.html &&
"'! rg -q '"'<(video|img|iframe)|https?://|animation:|transition:' index.html &&
printf 'PASS: table rows, options, initial count, original filter script, and no added media/motion/external URLs.\\n'"
